            "description": "当前相对湿度百分比",
            "sampleValue": 68
          },
          "alertLevel": {
            "type": "string",
            "description": "暴雨降温等天气风险提示",
            "sampleValue": "暴雨降温"
          }
        },
        "daily": [
          {
            "weekday": {
              "type": "string",
              "description": "第一天星期展示文本",
              "sampleValue": "今天"
            },
