              "description": "第一天温度范围展示文本",
              "sampleValue": "16°/21°"
            },
            "rainProbabilityPercent": {
              "type": "string",
              "description": "第一天降雨概率百分比",
              "sampleValue": "90%"
            }
          },
          {
            "weekday": {
              "type": "string",
              "description": "第二天星期展示文本",
              "sampleValue": "明天"
            },
            "condition": {
              "type": "string",
              "description": "第二天天气现象",
              "sampleValue": "小雨"
            },
            "temperatureRangeText": {
              "type": "string",
              "description": "第二天温度范围展示文本",
              "sampleValue": "17°/23°"
            },
            "rainProbabilityPercent": {
              "type": "string",
              "description": "第二天降雨概率百分比",
              "sampleValue": "70%"
            }
          },
          {
            "weekday": {
              "type": "string",
              "description": "第三天星期展示文本",
              "sampleValue": "周六"
            },
            "condition": {
              "type": "string",
              "description": "第三天天气现象",
              "sampleValue": "阴"
            },
            "temperatureRangeText": {
              "type": "string",
              "description": "第三天温度范围展示文本",
              "sampleValue": "19°/25°"
            },
            "rainProbabilityPercent": {
              "type": "string",
              "description": "第三天降雨概率百分比",
              "sampleValue": "35%"
            }
          }
        ]
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/rain.png",
      "description": "云朵和雨滴组合的彩色天气图标，适合表达降雨、暴雨风险和天气关怀状态。"
    }
  ]
}

